<script setup>
import { ref,onMounted,computed } from 'vue';import { DoorOpen,CalendarDays,CreditCard,FileCheck,ArrowUpRight,ArrowRight } from 'lucide-vue-next';import { api } from '../lib/api';import { dateText,currency,today,label } from '../lib/format';import StatePanel from '../components/StatePanel.vue';import StatusBadge from '../components/StatusBadge.vue';
const data=ref(null),recent=ref([]),loading=ref(true),error=ref('');const totalRooms=computed(()=>data.value?.rooms.reduce((s,r)=>s+Number(r.count),0)||0);const roomColors={available:'#087b70',occupied:'#6a75b8',cleaning:'#d8a047',maintenance:'#dd7967',inactive:'#bbc5c3'};
async function load(){loading.value=true;error.value='';try{const [a,b]=await Promise.all([api('/admin/dashboard'),api('/admin/bookings?limit=5')]);data.value=a.data;recent.value=b.data;}catch(e){error.value=e.message;}finally{loading.value=false;}}onMounted(load);
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">HOTEL OVERVIEW</p><h1>ทุกการเข้าพัก อยู่ในการดูแล</h1><p class="muted">ภาพรวมโรงแรม · {{ dateText(today()) }}</p></div><RouterLink to="/admin/bookings" class="btn primary">ดูการจองทั้งหมด <ArrowUpRight :size="17"/></RouterLink></div><StatePanel :loading="loading" :error="error" @retry="load"/><template v-if="data&&!loading"><div class="stat-grid"><article class="stat-card"><span class="stat-icon"><DoorOpen/></span><small>ห้องพักทั้งหมด</small><strong>{{ totalRooms }} <span>ห้อง</span></strong><p>ดูสถานะความพร้อมของห้องพัก</p></article><article class="stat-card"><span class="stat-icon purple"><CalendarDays/></span><small>รอเข้าพักวันนี้</small><strong>{{ data.arrivals_today }} <span>การจอง</span></strong><p>การจองที่ยืนยันแล้ว</p></article><RouterLink to="/admin/payments" class="stat-card"><span class="stat-icon amber"><CreditCard/></span><small>รอตรวจชำระเงิน</small><strong>{{ data.pending_payments }} <span>รายการ</span></strong><p>ตรวจสอบหลักฐานการชำระเงิน →</p></RouterLink><RouterLink to="/admin/documents" class="stat-card"><span class="stat-icon blue"><FileCheck/></span><small>รอตรวจเอกสาร</small><strong>{{ data.pending_documents }} <span>รายการ</span></strong><p>ยืนยันข้อมูลก่อนเข้าพัก →</p></RouterLink></div><div class="dashboard-grid"><section class="panel"><div class="section-heading"><div><h2>สถานะห้องพัก</h2><p class="muted">ความพร้อมของห้องในขณะนี้</p></div><RouterLink to="/admin/rooms" class="icon-link"><ArrowUpRight :size="18"/></RouterLink></div><div class="room-status-bar"><span v-for="r in data.rooms" :key="r.room_status" :style="{width:(Number(r.count)/totalRooms*100)+'%',background:roomColors[r.room_status]}" :title="label(r.room_status)+': '+r.count"></span></div><div class="status-breakdown"><div v-for="r in data.rooms" :key="r.room_status"><span class="legend-dot" :style="{background:roomColors[r.room_status]}"></span><span>{{ label(r.room_status) }}</span><strong>{{ r.count }}</strong></div></div></section><section class="panel workflow-panel"><p class="eyebrow">DAILY WORKFLOW</p><h2>เตรียมพร้อมสำหรับผู้เข้าพัก</h2><div><span>01</span><p>ตรวจการชำระเงินและเอกสาร</p></div><div><span>02</span><p>ตรวจว่าห้องสะอาดและพร้อมใช้งาน</p></div><div><span>03</span><p>Check-in และดูแลการเข้าพัก</p></div><RouterLink to="/admin/bookings" class="text-link">ไปจัดการการจอง <ArrowRight :size="17"/></RouterLink></section></div><section class="panel table-panel"><div class="section-heading padded"><div><h2>การจองล่าสุด</h2><p class="muted">รายการใหม่จากลูกค้า</p></div><RouterLink to="/admin/bookings" class="text-link">ดูทั้งหมด <ArrowRight :size="16"/></RouterLink></div><StatePanel :empty="!recent.length"/><div v-if="recent.length" class="table-scroll"><table><thead><tr><th>การจอง</th><th>ผู้เข้าพัก</th><th>วันเข้าพัก</th><th>ค่าห้องรวม</th><th>สถานะ</th><th></th></tr></thead><tbody><tr v-for="b in recent" :key="b.booking_id"><td><strong>{{ b.booking_number }}</strong></td><td>{{ b.first_name }} {{ b.last_name }}</td><td>{{ dateText(b.check_in_date) }}</td><td>{{ currency(b.total_amount) }}</td><td><StatusBadge :value="b.booking_status"/></td><td><RouterLink :to="'/bookings/'+b.booking_id" class="icon-link" aria-label="ดูรายละเอียด"><ArrowUpRight :size="17"/></RouterLink></td></tr></tbody></table></div></section></template></section></template>
